import{_ as i,l,o as e,c as n,v as r,p as s,x as o,d,i as c,S as h}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"布尔代数公理","description":"","frontmatter":{"title":"布尔代数公理","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/boolean-algebra.md","filePath":"cs/boolean-algebra.md","lastUpdated":1789023840000}'),p={name:"cs/boolean-algebra.md"};function E(_,a,m,b,u,f){const t=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=r('<h1 id="布尔代数公理" tabindex="-1">布尔代数公理 <a class="header-anchor" href="#布尔代数公理" aria-label="Permalink to &quot;布尔代数公理&quot;">​</a></h1><div class="epigraph"><p>把真与假当成代数里的两个元，与、或、非就有交换、分配和互补，化简才不是靠猜。</p><footer>—— 据 Boole, The Laws of Thought, 1854；Shannon, A Symbolic Analysis of Relay and Switching Circuits, 1938；Harris and Harris, Digital Design and Computer Architecture 整理</footer></div><p>上一课<a href="/cs/parity-crc">奇偶与 CRC</a>把冗余写成汉明距离，校验位「看起来像异或」，但还没有一套对 \\(\\{0,1\\}\\) 的运算。本课不重讲码字几何，也不从「逻辑学史」另起。缺口是：比特到现在只有区分、读法和距离，<strong>没有函数</strong>。门电路、后课的组合网络，需要先承认与、或、非满足的公理。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>纠错的校验、后课的加法器进位，都是「若干比特进、若干比特出」。若每次都列真值表，规模随输入指数涨。缺口因此不是新的物理判决，而是把 \\(\\{0,1\\}\\) 上的运算做成代数：交换、结合、分配、De Morgan、互补 \\(x+\\bar x=1\\)、\\(x\\cdot\\bar x=0\\)。有了这些，表达式才能等价变形。</p><p>Shannon 1938 把继电器接点与布尔代数对应起来。本课只钉公理与对偶；最小项展开、卡诺图是后课。晶体管实现是<a href="/cs/cmos-inverter">CMOS 反相器</a>才开始的另一课程。</p><h3 id="布尔不是「真值表的别名」" tabindex="-1">布尔不是「真值表的别名」 <a class="header-anchor" href="#布尔不是「真值表的别名」" aria-label="Permalink to &quot;布尔不是「真值表的别名」&quot;">​</a></h3><p>真值表是函数的外延。代数给的是改写规则：同一函数可以有许多式子。后课化简要的是更短的式子，不是另一张表。把 \\(+\\) 当成整数加、把溢出规则带进来，会把本课毁掉：这里 \\(1+1=1\\)。</p><p><span class="marginnote">Harris 把组合逻辑写成布尔式再画门。Boole 的原书对象更宽；本栏只用二元布尔代数。第一课的 0/1 在这里第一次获得「假/真」解释，仍不绑定高电平。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>载体 \\(\\{0,1\\}\\)，运算 \\(\\cdot\\)、\\(+\\)、\\(\\overline{\\,\\cdot\\,}\\)（与、或、非）。公理保证它是有补分配格。对偶原理：把 \\(0/1\\) 与 \\(\\cdot/+\\) 对换，定理仍真。任一 \\(n\\) 元函数都是某个式子——存在性下节最小项才构造；本课只要求运算封闭、可结合，以便后课画多级门。</p>',11)),(e(),s(h,null,{default:o(()=>[c(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20BIT%5B%22%E6%AF%94%E7%89%B9%22%5D%20--%3E%20ALG%5B%22%E4%B8%8E%E3%80%81%E6%88%96%E3%80%81%E9%9D%9E%E5%85%AC%E7%90%86%22%5D%0A%20%20ALG%20--%3E%20EQ%5B%22%E7%AD%89%E4%BB%B7%E5%8F%98%E5%BD%A2%22%5D%0A%20%20EQ%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E6%9C%80%E5%B0%8F%E9%A1%B9%E4%B8%8E%E5%8C%96%E7%AE%80%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>有了代数，组合电路的功能可以先写式子再映射到门。等价的式子对应功能相同、延迟和门数可以不同——代价是后课时延才量化。纠错码里的偶校验就是 \\(x_1+\\cdots+x_n\\) 在模 2 下；本课的 \\(+\\) 是或，模 2 加是另一运算（异或），后课会当组合块用，本课不把它提升成公理原语。</p><p>互补律让「非」成为对合：两次非回到自身。这是后课反相器链的功能面；电气上的奇数个反相器振荡，是器件课的缺口。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入时序、不把布尔环（\\(\\mathbb{F}_2\\) 上的多项式）整章搬进来，也不讨论多值逻辑。集合论还没有：布尔代数可以解释成幂集运算，那是<a href="/cs/sets-relations">集合与关系</a>的对照，不是本课定义。</p><p>后课默认：组合功能是布尔函数；化简与实现都在这套公理上改写，不再从 Boole 重讲。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>与、或、非满足交换、分配、De Morgan 与互补。</li><li>\\(1+1=1\\)，不是整数加；异或是后课组合块。</li><li>公理给等价变形；最短式与真值表枚举是后课。</li><li>出处：Boole, 1854；Shannon, 1938；Harris and Harris。</li></ul>',8))])}const x=i(p,[["render",E]]);export{B as __pageData,x as default};
